actions.action:
pu_proces: f.pu_proces, pu_stav_label: f.pu_stav_label, pu_pridelene: f.pu_pridelene,
pu_vysledok: f.pu_vysledok;

// Ponuka procesov sa cita z instancie, nie z tohto XML - nova appka sa tu
// objavi sama. Obnovuje sa aj pri kazdom otvoreni ulohy (assign).
change pu_proces options { processOptions() }
change pu_authority options { authorityOptions() }
change pu_stav_label value { "Unlinked" }
change pu_pridelene value { "(nothing yet)" }
change pu_vysledok value {
    "This case is not linked to any account.\n" +
    "Accounts are created in the \"New user\" view. Delete this case."
}
changeCaseProperty("color").about { "red" }

document.function:
{ def u ->
    // `?.` chráni pred null, nie pred chýbajúcou property.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def snap ->
    // Stav uctu podla `UserState` enginu. Pribudol s pozvankami: ucet
    // pozvaneho cloveka existuje uz od odoslania pozvanky, ale este nema meno
    // ani heslo - a bez tohto rozlisenia vyzera v zozname ako hotovy ucet
    // s prazdnym menom, co sa neda odlisit od chyby.
    //
    // BLOCKED nie je ban. Do toho stavu prepne ucet `/api/auth/reset`, teda
    // ziadost o obnovu hesla, a trva len kym si clovek nove heslo nenastavi.
    def stav = ((snap?.stav ?: "ACTIVE") as String)
    if (stav == "INVITED") return "Invited"
    if (stav == "BLOCKED") return "Waiting for a new password"
    return "Active"
}

{ def snap ->
    def stav = ((snap?.stav ?: "ACTIVE") as String)
    return (stav == "ACTIVE") ? "green" : "orange"
}

{ def pole ->
    // Hodnota multichoice_map je zoznam klucov, ale cez REST aj z UI prichadza
    // v roznych obalkach. Bez tohto by sa `each` prehnal po znakoch retazca.
    def raw = pole.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def pu_zoznam ->
    // Akumulator je text, jeden riadok = "importId|siet|verzia". Tabulator by
    // sa cez REST aj cez formular stratil, zvisla ciara nie.
    def out = []
    ((pu_zoznam.value ?: "") as String).split("\n").each { String riadok ->
        def r = riadok.trim()
        if (!r) return
        def casti = r.split("\\|", -1)
        if (casti.length < 2) return
        out << [rola: casti[0], siet: casti[1], verzia: (casti.length > 2 ? casti[2] : "vsetky")]
    }
    return out
}

{ def polozky ->
    if (!polozky) return "(nothing yet)"
    return polozky.collect { p ->
        def v = (p.verzia == null || p.verzia == "" || p.verzia == "vsetky")
                ? "all versions" : ("verzia " + (p.verzia as String).replace("_", "."))
        return "• " + p.rola + " — " + p.siet + " (" + v + ")"
    }.join("\n")
}

{ def polozky ->
    return polozky.collect { it.rola + "|" + it.siet + "|" + it.verzia }.join("\n")
}

{ def snap ->
    // Zo skutocneho stavu uctu na riadky akumulatora. Berie UZ NACITANY
    // snapshot - `userSnapshot` stavi index rol vsetkych sieti, takze druhe
    // volanie na tom istom ucte je zbytocna praca; pri zosuladeni 15 uctov to
    // bola polovica casu.
    //
    // Verzia je "vsetky": snapshot verzie nerozlisuje a plosne pridelenie je
    // aj tak to, co clovek chce skoro vzdy.
    def out = []
    ((snap?.roly ?: [:]) as Map).each { siet, zoznamRoli ->
        (zoznamRoli ?: []).each { rola -> out << (rola + "|" + siet + "|vsetky") }
    }
    return out.join("\n")
}

actions.action:
pu_userid: f.pu_userid, pu_meno: f.pu_meno, pu_priezvisko: f.pu_priezvisko,
pu_email: f.pu_email, pu_authority: f.pu_authority, pu_zoznam: f.pu_zoznam,
pu_pridelene: f.pu_pridelene, pu_stav_label: f.pu_stav_label, pu_vysledok: f.pu_vysledok;

// ZVIAZANIE PRIPADU S UCTOM je tu, na jednom mieste. `pu_zalozenie` teda
// nastavi len `pu_userid` a zvysok si pripad dotiahne sam z uctu - ucet je
// zdroj pravdy, nie to, co niekto poslal.
//
// Preco na `pu_userid` a nie na `pu_email`: pri jednom `setData` s viacerymi
// polami nie je poradie klucov zarucene, takze udalost na e-maile by mohla
// bezat este pred nastavenim id a nemala by z coho citat.
def id = ((pu_userid.value ?: "") as String).trim()
if (!id) {
    return
}
def snap = userSnapshot(id)
if (!snap || !snap.email) {
    change pu_stav_label value { "The account does not exist" }
    changeCaseProperty("color").about { "red" }
    return
}
// Moznosti PRED hodnotou - inak ju engine odmietne.
change pu_proces options { processOptions() }
change pu_authority options { authorityOptions() }
change pu_meno value { snap.meno }
change pu_priezvisko value { snap.priezvisko }
change pu_email value { snap.email }
change pu_authority value { (snap.authorities ?: []) as List }
change pu_zoznam value { roly_uctu(snap) }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
change pu_stav_label value { stav_popis(snap) }
change pu_vysledok value { "" }
changeCaseProperty("title").about { nazov(pu_meno, pu_priezvisko, pu_email) }
changeCaseProperty("color").about { stav_farba(snap) }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia;

// Druhy krok vyberu: z vybraneho procesu sa doplnia JEHO role a JEHO verzie.
def siet = (pu_proces.value ?: "") as String
change pu_roly options { processRoleOptions(siet) }
change pu_roly value { [] }
change pu_verzia options { processVersionOptions(siet) }
change pu_verzia value { "vsetky" }

pu_proces: f.pu_proces, pu_roly: f.pu_roly, pu_verzia: f.pu_verzia,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

// Bez tlacidla by vyber druheho procesu prepisal ten prvy: `pu_roly` drzi
// role len prave vybraneho procesu.
def siet = (pu_proces.value ?: "") as String
def verzia = ((pu_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(pu_roly)
if (siet && vybrane) {
    def riadky = rozbor_zoznamu(pu_zoznam).collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change pu_zoznam value { riadky.join("\n") }
    change pu_roly value { [] }
}
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }

pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene;

change pu_zoznam value { "" }
change pu_pridelene value { "(nothing yet)" }

pu_proces: f.pu_proces, pu_userid: f.pu_userid, pu_zoznam: f.pu_zoznam,
pu_pridelene: f.pu_pridelene, pu_authority: f.pu_authority, pu_meno: f.pu_meno,
pu_priezvisko: f.pu_priezvisko, pu_email: f.pu_email, pu_stav_label: f.pu_stav_label;

// Pri KAZDOM otvoreni sa stav uctu nacita znova. Bez toho by uprava pracovala
// s tym, co platilo pri zalozeni pripadu - a keby niekto medzitym zmenil rolu
// inde, admin by to prepisal starym stavom.
change pu_proces options { processOptions() }
change pu_authority options { authorityOptions() }

def id = ((pu_userid.value ?: "") as String).trim()
if (!id) {
    return
}
def snap = userSnapshot(id)
if (!snap || !snap.email) {
    change pu_stav_label value { "The account does not exist" }
    changeCaseProperty("color").about { "red" }
    return
}
change pu_meno value { snap.meno }
change pu_priezvisko value { snap.priezvisko }
change pu_email value { snap.email }
change pu_authority value { (snap.authorities ?: []) as List }
change pu_zoznam value { roly_uctu(snap) }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
change pu_stav_label value { stav_popis(snap) }
changeCaseProperty("title").about { nazov(pu_meno, pu_priezvisko, pu_email) }
changeCaseProperty("color").about { stav_farba(snap) }

pu_userid: f.pu_userid, pu_heslo: f.pu_heslo, pu_authority: f.pu_authority;

def id = ((pu_userid.value ?: "") as String).trim()
if (!id) {
    throw new java.lang.IllegalStateException(
            "This case is not linked to any account. Accounts are created " +
            "in the \"New user\" view; delete this case.")
}
if (findUserById(id) == null) {
    throw new java.lang.IllegalStateException("Account not found: " + id)
}
def heslo = formPassword(pu_heslo.value)
if (heslo && !registrationService.isPasswordSufficient(heslo)) {
    throw new java.lang.IllegalStateException("The new password does not meet this instance's requirements.")
}
if (!ako_zoznam(pu_authority).contains("ROLE_USER")) {
    throw new java.lang.IllegalStateException(
            "Without ROLE_USER the person can log in but will see no views at all.")
}

pu_userid: f.pu_userid, pu_meno: f.pu_meno, pu_priezvisko: f.pu_priezvisko,
pu_email: f.pu_email, pu_heslo: f.pu_heslo, pu_authority: f.pu_authority,
pu_zoznam: f.pu_zoznam, pu_pridelene: f.pu_pridelene, pu_stav_label: f.pu_stav_label,
pu_vysledok: f.pu_vysledok, pu_zmenil: f.pu_zmenil, pu_zmenene_o: f.pu_zmenene_o;

// Ucet sa NEDRZI ako objekt - kazda zmena uklada cely dokument, takze dve
// zmeny cez ten isty objekt by sa navzajom prepisali (PETRIFLOW_LEARNINGS B10).
def id = ((pu_userid.value ?: "") as String).trim()
def predtym = userSnapshot(id)
def authorities = ako_zoznam(pu_authority)
def heslo = formPassword(pu_heslo.value)
def riadky = []

updateUserProfile(id, ((pu_meno.value ?: "") as String).trim(),
                      ((pu_priezvisko.value ?: "") as String).trim())
setUserAuthorities(id, authorities)
if (heslo) {
    changeUserPassword(id, heslo)
    riadky << "password changed"
}
riadky << ("system authorities: " + (authorities ? authorities.join(", ") : "none"))

// Uprava je NASTAVENIE stavu, nie pridavanie - co v zozname nie je, sa odoberie,
// inak by sa rola nedala nikdy zrusit.
def chceme = rozbor_zoznamu(pu_zoznam).collect { it.rola + "|" + it.siet } as Set
((predtym.roly ?: [:]) as Map).each { siet, zoznamRoli ->
    (zoznamRoli ?: []).each { rola ->
        if (!chceme.contains((rola as String) + "|" + (siet as String))) {
            setProcessRole(id, rola as String, siet as String, "", false)
            riadky << ("role removed: " + rola + " (" + siet + ")")
        }
    }
}

def pridelene = []
def zlyhane = []
rozbor_zoznamu(pu_zoznam).each { p ->
    if (setProcessRole(id, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "process roles: " + pridelene.join(", ") : "process roles: none")
if (zlyhane) {
    riadky << ("COULD NOT assign: " + zlyhane.join(", "))
}

// `predtym` je snapshot PRED zmenami - stav sa musi nacitat znova, inak by
// ucet, ktoremu prave niekto nastavil heslo, zostal navzdy "Invited".
def potom = userSnapshot(id)
change pu_stav_label value {
    zlyhane ? (stav_popis(potom) + " with a caveat") : stav_popis(potom)
}
change pu_vysledok value { riadky.join("\n") }
change pu_pridelene value { popis_zoznamu(rozbor_zoznamu(pu_zoznam)) }
change pu_zmenil value { kto(loggedUser()) }
change pu_zmenene_o value { java.time.LocalDateTime.now() }

// Heslo z pripadu prec. Zostalo by v datach citatelne pre kazdeho, kto ma
// na case `view` - a to je pri sprave uzivatelov to posledne, co chceme.
change pu_heslo value { "" }

changeCaseProperty("title").about { nazov(pu_meno, pu_priezvisko, pu_email) }
changeCaseProperty("color").about { zlyhane ? "orange" : stav_farba(potom) }
